// WP_SPINE_ROW_GROUPS=2 end-to-end test on CPU.
//
// A tiny synthetic DeepSeek-V4.1 model that carries the REAL per-layer layout of
// the production GGUF (compress ratios, kv/index source layers, engram layers;
// see test-dsv41-rowgroup-layout.inc, generated by scripts/gen-dsv41-rowgroup-layout.py).
// Each verify-shaped ubatch (R rows at positions p0..p0+R-1) is decoded once with
// WP_SPINE_ROW_GROUPS unset and once with =2, and the final logits and a few
// per-layer input taps are compared. Each row-group run must report the gate as
// "active" (WP_SPINE_ROW_GROUPS_LOG), so the comparison cannot silently be
// fallback-vs-fallback.
//
// Also: a host-side port of /tmp/claude-1000/ss/sim_layers.py. Every compressed row
// a row group can see must be written before that group's attention runs, over the
// real layer table. The shared-stash check must pass; the per-lane-stash variant
// (the pre-fix bug) must be detected.
//
// Tolerance: the two row groups run their matmuls at a different batch shape, so
// the CPU result is not bit-identical. Differences are reported; a structural error
// (wrong rows / wrong state) is orders of magnitude larger.

#include "ggml-backend.h"
#include "ggml-cpp.h"
#include "gguf.h"
#include "llama-cpp.h"
#include "llama.h"

#include "../src/llama-arch.h"
#include "../src/llama-ext.h"
#include "../src/llama-model-saver.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstdint>
#include <cstring>
#include <map>
#include <random>
#include <set>
#include <string>
#include <vector>

#include "test-dsv41-rowgroup-layout.inc"

namespace {

// ---------------------------------------------------------------------------
// Tiny dimensions (the layer table above is the real one).
// ---------------------------------------------------------------------------
constexpr int64_t E       = 64;   // n_embd
constexpr int64_t H       = 4;    // n_head
constexpr int64_t D       = 64;   // n_embd_head (lightning-indexer Hadamard needs >= 64)
constexpr int64_t QL      = 32;   // q_lora_rank
constexpr int64_t G       = 4;    // output group count
constexpr int64_t OL      = 16;   // output lora rank
constexpr int64_t HC      = 4;    // hc_mult
constexpr int64_t HCD     = E * HC;        // hc_dim
constexpr int64_t HCM     = (2 + HC) * HC; // hc_mix_dim
constexpr int64_t FF      = 64;   // expert ffn width
constexpr int64_t NE      = 4;    // experts
constexpr int64_t EU      = 2;    // experts used
constexpr int64_t SH      = 1;    // shared experts
constexpr int64_t IH      = 4;    // indexer heads
constexpr int64_t IK      = 64;   // indexer key length
constexpr int64_t V       = 128;  // vocab
constexpr uint32_t NCTX   = 512;

constexpr uint32_t ENG_HEADS    = 2;
constexpr uint32_t ENG_HEAD_DIM = 16;
constexpr uint32_t ENG_NGRAM    = 4;
constexpr uint32_t ENG_VOCAB    = 16;
constexpr uint32_t ENG_PAD      = 2;
constexpr uint32_t ENG_COMP_VOCAB = 8;

// layers whose input we tap and compare (per-layer hidden states)
const std::vector<uint32_t> tap_layers = { 3, 9, 15, 21, 39 };

bool in_list(const uint32_t * ids, size_t n, int il) {
    for (size_t i = 0; i < n; ++i) {
        if ((int) ids[i] == il) {
            return true;
        }
    }
    return false;
}
#define IN_LIST(arr, il) in_list(arr, sizeof(arr) / sizeof((arr)[0]), (il))

bool is_kv_source(int il)    { return rg_layout_kv_source[il] == il; }
bool is_index_source(int il) { return IN_LIST(rg_layout_index_source_ids, il); }
bool is_engram(int il)       { return IN_LIST(rg_layout_engram_layer_ids, il); }

constexpr uint32_t rg_layout_engram_n = sizeof(rg_layout_engram_layer_ids) / sizeof(rg_layout_engram_layer_ids[0]);

uint32_t engram_ordinal(int il) {
    for (uint32_t e = 0; e < rg_layout_engram_n; ++e) {
        if ((int) rg_layout_engram_layer_ids[e] == il) {
            return e;
        }
    }
    return 0;
}

// engram table rows per engram layer, with the loader's prime search (llama_model_deepseek41
// engram.primes): the `seen` set is shared across layers, so the ranges stay disjoint.
std::vector<uint32_t> engram_rows_per_layer() {
    const auto is_prime = [](int64_t n) {
        if (n < 2) return false;
        if (n % 2 == 0) return n == 2;
        for (int64_t d = 3; d * d <= n; d += 2) {
            if (n % d == 0) return false;
        }
        return true;
    };
    const uint32_t kinds = ENG_NGRAM > 1 ? ENG_NGRAM - 1 : 1;
    std::set<int64_t> seen;
    std::vector<uint32_t> rows;
    for (uint32_t layer = 0; layer < rg_layout_engram_n; ++layer) {
        int64_t offset = 0;
        for (uint32_t ng = 0; ng < kinds; ++ng) {
            int64_t current = (int64_t) ENG_VOCAB - 1;
            for (uint32_t h = 0; h < ENG_HEADS; ++h) {
                int64_t candidate = current + 1;
                while (!is_prime(candidate) || seen.count(candidate)) {
                    ++candidate;
                }
                seen.insert(candidate);
                current = candidate;
                offset += candidate;
            }
        }
        rows.push_back((uint32_t) offset);
    }
    return rows;
}

void add_meta(struct gguf_context * ctx, const std::string & name, std::vector<int64_t> ne) {
    ggml_tensor t = {};
    t.type = GGML_TYPE_F32;
    for (int i = 0; i < 4; ++i) {
        t.ne[i] = i < (int) ne.size() ? ne[i] : 1;
    }
    t.nb[0] = sizeof(float);
    for (int i = 1; i < 4; ++i) {
        t.nb[i] = t.nb[i - 1] * t.ne[i - 1];
    }
    ggml_set_name(&t, name.c_str());
    gguf_add_tensor(ctx, &t);
}

std::string blk(int il, const char * suffix) {
    return "blk." + std::to_string(il) + "." + suffix;
}

void set_tensor_data_f32(struct ggml_tensor * tensor, void * /*userdata*/) {
    const int64_t ne = ggml_nelements(tensor);
    uint32_t seed = 2166136261u;
    const char * name = ggml_get_name(tensor);
    for (const char * p = name; p != nullptr && *p != '\0'; ++p) {
        seed = (seed ^ (uint8_t) *p) * 16777619u;
    }
    const auto weight = [seed, name](int64_t i) {
        uint32_t x = seed ^ (uint32_t) i ^ (uint32_t) (i >> 32);
        x ^= x >> 16;
        x *= 0x7feb352du;
        x ^= x >> 15;
        x *= 0x846ca68bu;
        x ^= x >> 16;
        const float unit = 2.0f * (float) (x & 0xffffu) / 65535.0f - 1.0f;
        return name != nullptr && std::strstr(name, "norm") != nullptr ? 1.0f + 0.01f * unit : 0.05f * unit;
    };
    std::vector<float> tmp(ne);
    for (int64_t i = 0; i < ne; ++i) {
        tmp[i] = weight(i);
    }
    ggml_backend_tensor_set(tensor, tmp.data(), 0, ggml_nbytes(tensor));
}

gguf_context_ptr make_gguf() {
    gguf_context_ptr ret(gguf_init_empty());
    llama_model_saver ms(LLM_ARCH_DEEPSEEK41, ret.get());

    const uint32_t n_layer = rg_layout_n_layer;
    ms.add_kv(LLM_KV_GENERAL_ARCHITECTURE,      llm_arch_name(LLM_ARCH_DEEPSEEK41));
    ms.add_kv(LLM_KV_VOCAB_SIZE,                (uint32_t) V);
    ms.add_kv(LLM_KV_CONTEXT_LENGTH,            NCTX);
    ms.add_kv(LLM_KV_EMBEDDING_LENGTH,          (uint32_t) E);
    ms.add_kv(LLM_KV_FEATURES_LENGTH,           (uint32_t) E);
    ms.add_kv(LLM_KV_BLOCK_COUNT,               n_layer);
    ms.add_kv(LLM_KV_LEADING_DENSE_BLOCK_COUNT, uint32_t(0));
    ms.add_kv(LLM_KV_ATTENTION_HEAD_COUNT,      (uint32_t) H);
    ms.add_kv(LLM_KV_ATTENTION_HEAD_COUNT_KV,   uint32_t(1));
    ms.add_kv(LLM_KV_ATTENTION_KEY_LENGTH,      (uint32_t) D);
    ms.add_kv(LLM_KV_ATTENTION_VALUE_LENGTH,    (uint32_t) D);
    ms.add_kv(LLM_KV_ROPE_DIMENSION_COUNT,      (uint32_t) (D / 2));
    ms.add_kv(LLM_KV_ATTENTION_LAYERNORM_RMS_EPS, 1e-5f);
    ms.add_kv(LLM_KV_ATTENTION_Q_LORA_RANK,     (uint32_t) QL);
    ms.add_kv(LLM_KV_ATTENTION_SLIDING_WINDOW,  rg_layout_n_swa);
    ms.add_kv(LLM_KV_ATTENTION_INDEXER_HEAD_COUNT, (uint32_t) IH);
    ms.add_kv(LLM_KV_ATTENTION_INDEXER_KEY_LENGTH, (uint32_t) IK);
    ms.add_kv(LLM_KV_ATTENTION_INDEXER_TOP_K,      uint32_t(32));
    ms.add_kv(LLM_KV_ATTENTION_OUTPUT_GROUP_COUNT, (uint32_t) G);
    ms.add_kv(LLM_KV_ATTENTION_OUTPUT_LORA_RANK,   (uint32_t) OL);
    ms.add_kv(LLM_KV_ATTENTION_COMPRESS_RATIOS,
            std::vector<uint32_t>(rg_layout_compress_ratios, rg_layout_compress_ratios + n_layer));
    ms.add_kv(LLM_KV_ATTENTION_COMPRESS_ROPE_FREQ_BASE, 160000.0f);
    ms.add_kv(LLM_KV_HYPER_CONNECTION_COUNT,               (uint32_t) HC);
    ms.add_kv(LLM_KV_HYPER_CONNECTION_SINKHORN_ITERATIONS, uint32_t(20));
    ms.add_kv(LLM_KV_HYPER_CONNECTION_EPSILON,             1.0e-6f);
    ms.add_kv(LLM_KV_HASH_LAYER_COUNT,                     uint32_t(0));
    ms.add_kv(LLM_KV_SWIGLU_CLAMP_EXP,                     std::vector<float>(n_layer, rg_layout_swiglu_clamp));
    ms.add_kv(LLM_KV_EXPERT_FEED_FORWARD_LENGTH,           (uint32_t) FF);
    ms.add_kv(LLM_KV_EXPERT_COUNT,                         (uint32_t) NE);
    ms.add_kv(LLM_KV_EXPERT_USED_COUNT,                    (uint32_t) EU);
    ms.add_kv(LLM_KV_EXPERT_SHARED_COUNT,                  (uint32_t) SH);
    ms.add_kv(LLM_KV_EXPERT_GATING_FUNC,                   uint32_t(4)); // SQRT_SOFTPLUS
    ms.add_kv(LLM_KV_EXPERT_WEIGHTS_SCALE,                 1.0f);
    ms.add_kv(LLM_KV_EXPERT_WEIGHTS_NORM,                  true);
    ms.add_kv(LLM_KV_TOKENIZER_MODEL,                      "no_vocab");

    ms.add_kv(LLM_KV_ATTENTION_KV_SOURCE_LAYER_IDS,
            std::vector<uint32_t>(rg_layout_kv_source_ids, rg_layout_kv_source_ids + sizeof(rg_layout_kv_source_ids) / sizeof(uint32_t)));
    ms.add_kv(LLM_KV_ATTENTION_INDEX_SOURCE_LAYER_IDS,
            std::vector<uint32_t>(rg_layout_index_source_ids, rg_layout_index_source_ids + sizeof(rg_layout_index_source_ids) / sizeof(uint32_t)));
    ms.add_kv(LLM_KV_ATTENTION_CANDIDATE_SOURCE_LAYER_ID, rg_layout_candidate_src);
    ms.add_kv(LLM_KV_ATTENTION_CANDIDATE_TOPK_BLOCKS,     uint32_t(8));
    ms.add_kv(LLM_KV_ATTENTION_CANDIDATE_BLOCK_SIZE,      uint32_t(8));

    ms.add_kv(LLM_KV_ENGRAM_LAYER_IDS,
            std::vector<uint32_t>(rg_layout_engram_layer_ids, rg_layout_engram_layer_ids + sizeof(rg_layout_engram_layer_ids) / sizeof(uint32_t)));
    ms.add_kv(LLM_KV_ENGRAM_HEAD_COUNT,            ENG_HEADS);
    ms.add_kv(LLM_KV_ENGRAM_KEY_LENGTH,            ENG_HEAD_DIM);
    ms.add_kv(LLM_KV_ENGRAM_MAX_NGRAM_SIZE,        ENG_NGRAM);
    ms.add_kv(LLM_KV_ENGRAM_VOCAB_SIZE,            ENG_VOCAB);
    ms.add_kv(LLM_KV_ENGRAM_PAD_TOKEN_ID,          ENG_PAD);
    ms.add_kv(LLM_KV_ENGRAM_COMPRESSED_VOCAB_SIZE, ENG_COMP_VOCAB);

    // ----- tensors (F32, tiny shapes; names and roles follow load_arch_tensors) -----
    add_meta(ret.get(), "token_embd.weight",  { E, V });
    add_meta(ret.get(), "output_norm.weight", { E });
    add_meta(ret.get(), "output.weight",      { E, V });

    const uint32_t n_cols = (ENG_NGRAM > 1 ? ENG_NGRAM - 1 : 1) * ENG_HEADS;
    const std::vector<uint32_t> erows = engram_rows_per_layer();

    for (int il = 0; il < (int) n_layer; ++il) {
        add_meta(ret.get(), blk(il, "attn_norm.weight"),      { E });
        add_meta(ret.get(), blk(il, "attn_sinks.weight"),     { H });
        add_meta(ret.get(), blk(il, "attn_q_a.weight"),       { E, QL });
        add_meta(ret.get(), blk(il, "attn_q_a_norm.weight"),  { QL });
        add_meta(ret.get(), blk(il, "attn_q_b.weight"),       { QL, H * D });
        add_meta(ret.get(), blk(il, "attn_kv.weight"),        { E, D });
        add_meta(ret.get(), blk(il, "attn_kv_a_norm.weight"), { D });
        for (int64_t g = 0; g < G; ++g) {
            add_meta(ret.get(), blk(il, ("attn_output_a.g" + std::to_string(g) + ".weight").c_str()), { H * D / G, OL });
        }
        add_meta(ret.get(), blk(il, "attn_output_b.weight"),  { G * OL, E });
        add_meta(ret.get(), blk(il, "hc_attn_fn.weight"),     { HCD, HCM });
        add_meta(ret.get(), blk(il, "hc_attn_base.weight"),   { HCM });
        add_meta(ret.get(), blk(il, "hc_attn_scale.weight"),  { 3 });
        add_meta(ret.get(), blk(il, "hc_ffn_fn.weight"),      { HCD, HCM });
        add_meta(ret.get(), blk(il, "hc_ffn_base.weight"),    { HCM });
        add_meta(ret.get(), blk(il, "hc_ffn_scale.weight"),   { 3 });
        add_meta(ret.get(), blk(il, "ffn_norm.weight"),       { E });
        add_meta(ret.get(), blk(il, "ffn_gate_inp.weight"),   { E, NE });
        add_meta(ret.get(), blk(il, "exp_probs_b.bias"),      { NE });
        add_meta(ret.get(), blk(il, "ffn_gate_exps.weight"),  { E, FF, NE });
        add_meta(ret.get(), blk(il, "ffn_up_exps.weight"),    { E, FF, NE });
        add_meta(ret.get(), blk(il, "ffn_down_exps.weight"),  { FF, E, NE });
        add_meta(ret.get(), blk(il, "ffn_gate_shexp.weight"), { E, FF * SH });
        add_meta(ret.get(), blk(il, "ffn_up_shexp.weight"),   { E, FF * SH });
        add_meta(ret.get(), blk(il, "ffn_down_shexp.weight"), { FF * SH, E });

        if (is_kv_source(il) && rg_layout_compress_ratios[il] > 0) {
            add_meta(ret.get(), blk(il, "attn_compressor_kv.weight"),   { E, D });
            add_meta(ret.get(), blk(il, "attn_compressor_gate.weight"), { E, D });
            add_meta(ret.get(), blk(il, "attn_compressor_norm.weight"), { D });
        }
        if (is_index_source(il)) {
            add_meta(ret.get(), blk(il, "indexer.proj.weight"),    { E, IH });
            add_meta(ret.get(), blk(il, "indexer.attn_q_b.weight"), { QL, IH * IK });
        }
        if (is_kv_source(il)) {
            add_meta(ret.get(), blk(il, "indexer.attn_k.weight"), { D, IK });
            add_meta(ret.get(), blk(il, "indexer.k_norm.weight"), { IK });
        }
        if (is_engram(il)) {
            add_meta(ret.get(), blk(il, "engram_embd.weight"), { ENG_HEAD_DIM, erows[engram_ordinal(il)] });
            add_meta(ret.get(), blk(il, "engram_wkv.weight"),  { n_cols * ENG_HEAD_DIM, E * (HC + 1) });
        }
    }
    return ret;
}

llama_model_ptr load_model() {
    gguf_context_ptr gguf_ctx = make_gguf();
    llama_model_params model_params = llama_model_default_params();
    model_params.n_gpu_layers = 0;
    ggml_backend_dev_t cpu = ggml_backend_dev_by_type(GGML_BACKEND_DEVICE_TYPE_CPU);
    ggml_backend_dev_t devices[] = { cpu, nullptr };
    model_params.devices = devices;
    return llama_model_ptr(llama_model_init_from_user(gguf_ctx.get(), set_tensor_data_f32, nullptr, model_params));
}

// ---------------------------------------------------------------------------
// Gate observation: count WP_SPINE_ROW_GROUPS=2 gate lines by outcome.
// ---------------------------------------------------------------------------
// one entry per gate evaluation: (active?, R, reason)
struct GateEvent {
    bool active;
    uint32_t R;
    std::string reason;
};
std::vector<GateEvent> g_gate_events;

void log_cb(enum ggml_log_level level, const char * text, void * /*ud*/) {
    if (level == GGML_LOG_LEVEL_ERROR) {
        fputs(text, stderr);
        return;
    }
    const char * p = std::strstr(text, "WP_SPINE_ROW_GROUPS=2 ");
    if (p == nullptr) {
        return;
    }
    GateEvent ev{};
    ev.active = std::strncmp(p + 22, "active", 6) == 0;
    const char * r = std::strstr(p, " R=");
    ev.R = r != nullptr ? (uint32_t) std::strtoul(r + 3, nullptr, 10) : 0;
    const char * why = std::strstr(p, "reason=");
    ev.reason = why != nullptr ? why + 7 : "";
    g_gate_events.push_back(ev);
}

void set_env(const char * name, const char * value) {
    if (value != nullptr) {
        setenv(name, value, 1);
    } else {
        unsetenv(name);
    }
}

// ---------------------------------------------------------------------------
// One run: prefill p0 tokens, then one verify ubatch of R rows (optionally
// rolled back and re-verified). Returns final logits (R x V) and taps.
// ---------------------------------------------------------------------------
struct RunResult {
    std::vector<float> logits;                   // R * V, row-major (batch order)
    std::map<uint32_t, std::vector<float>> taps; // layer -> R * E
    int active = 0;
    int fallback = 0;
    std::string fallback_reason;
    bool ok = false;
};

llama_context_ptr make_ctx(llama_model * model, uint32_t n_rs_seq) {
    llama_context_params cparams = llama_context_default_params();
    cparams.n_ctx     = NCTX;
    cparams.n_batch   = 512;
    cparams.n_ubatch  = 512;
    cparams.n_seq_max = 1;
    cparams.n_threads       = 8;
    cparams.n_threads_batch = 8;
    cparams.flash_attn_type = LLAMA_FLASH_ATTN_TYPE_DISABLED;
    cparams.n_rs_seq = n_rs_seq;
    return llama_context_ptr(llama_init_from_model(model, cparams));
}

std::vector<llama_token> make_tokens(uint32_t count, uint32_t seed) {
    std::mt19937 rng(seed);
    std::uniform_int_distribution<int32_t> dist(0, (int32_t) V - 1);
    std::vector<llama_token> t(count);
    for (auto & x : t) {
        x = (llama_token) dist(rng);
    }
    return t;
}

// positions pos0..pos0+n-1 for seq 0; all_logits: every row outputs logits (verify),
// otherwise only the last row (history)
bool decode_all(llama_context * ctx, const std::vector<llama_token> & tokens, llama_pos pos0, bool all_logits) {
    llama_batch batch = llama_batch_init((int32_t) tokens.size(), 0, 1);
    for (size_t i = 0; i < tokens.size(); ++i) {
        batch.token[i]     = tokens[i];
        batch.pos[i]       = pos0 + (llama_pos) i;
        batch.n_seq_id[i]  = 1;
        batch.seq_id[i][0] = 0;
        batch.logits[i]    = all_logits || i + 1 == tokens.size();
    }
    batch.n_tokens = (int32_t) tokens.size();
    const bool ok = llama_decode(ctx, batch) == 0;
    llama_batch_free(batch);
    return ok;
}

bool capture(llama_context * ctx, uint32_t R, RunResult & out) {
    out.logits.clear();
    for (uint32_t i = 0; i < R; ++i) {
        const float * l = llama_get_logits_ith(ctx, (int32_t) i);
        if (l == nullptr) {
            return false;
        }
        out.logits.insert(out.logits.end(), l, l + V);
    }
    out.taps.clear();
    for (uint32_t lid : tap_layers) {
        const float * t = llama_get_embeddings_layer_inp(ctx, lid);
        if (t == nullptr) {
            return false;
        }
        out.taps[lid].assign(t, t + R * E);
    }
    return true;
}

// rollback: after the first verify, drop back to p0 and verify again; the second
// verify's outputs are the ones compared.
RunResult run_case(llama_model * model, uint32_t R, uint32_t p0, bool rollback, bool topk_reuse, bool row_groups) {
    RunResult out;
    set_env("WP_DSV41_TOPK_REUSE", topk_reuse ? "1" : nullptr);
    set_env("WP_SPINE_ROW_GROUPS_LOG", "1");

    llama_context_ptr ctx = make_ctx(model, rollback ? R : 0);
    if (!ctx) {
        fprintf(stderr, "run_case: context creation failed\n");
        return out;
    }
    for (uint32_t lid : tap_layers) {
        llama_set_embeddings_layer_inp(ctx.get(), lid, true);
    }

    // history: always decoded with row groups off, so both runs share the same state
    set_env("WP_SPINE_ROW_GROUPS", nullptr);
    set_env("WP_SPINE_ROW_GROUPS_ALLOW_NO_DISPATCH", nullptr);
    if (p0 > 0) {
        if (!decode_all(ctx.get(), make_tokens(p0, 0x9E3779B9u + p0), 0, false)) {
            fprintf(stderr, "run_case: prefill failed (p0=%u)\n", p0);
            return out;
        }
    }

    // verify ubatch: row-group gate evaluated here
    const std::vector<llama_token> verify = make_tokens(R, 0x51A7u + 31u * R + p0);
    if (row_groups) {
        set_env("WP_SPINE_ROW_GROUPS", "2");
        set_env("WP_SPINE_ROW_GROUPS_ALLOW_NO_DISPATCH", "1");
    }
    g_gate_events.clear();

    bool ok_decode = decode_all(ctx.get(), verify, (llama_pos) p0, true);
    if (ok_decode && rollback) {
        // roll the KV/compressor state back to p0 and verify the same rows again. The
        // second decode normally reuses the first one's graph (same shape), so its gate
        // decision is the first event; the events are not cleared here.
        llama_memory_seq_rm(llama_get_memory(ctx.get()), 0, (llama_pos) p0, -1);
        ok_decode = decode_all(ctx.get(), verify, (llama_pos) p0, true);
    }
    if (!ok_decode) {
        fprintf(stderr, "run_case: verify decode failed (R=%u p0=%u rollback=%d)\n", R, p0, rollback);
        set_env("WP_SPINE_ROW_GROUPS", nullptr);
        set_env("WP_SPINE_ROW_GROUPS_ALLOW_NO_DISPATCH", nullptr);
        return out;
    }

    // only the gate evaluations of this verify graph count (the context's worst-case
    // reserve graph is built with R = n_ubatch and is not the graph under test)
    for (const GateEvent & ev : g_gate_events) {
        if (ev.R != R) {
            continue;
        }
        if (ev.active) {
            ++out.active;
        } else {
            ++out.fallback;
            out.fallback_reason = ev.reason;
        }
    }
    set_env("WP_SPINE_ROW_GROUPS", nullptr);
    set_env("WP_SPINE_ROW_GROUPS_ALLOW_NO_DISPATCH", nullptr);

    out.ok = capture(ctx.get(), R, out);
    return out;
}

// ---------------------------------------------------------------------------
// Host-side visibility check, port of /tmp/claude-1000/ss/sim_layers.py.
// ---------------------------------------------------------------------------
struct VisErrs {
    int unwritten = 0;   // a visible compressed row was not written yet
    int stash_missing = 0;
};

VisErrs visibility(uint32_t R, uint32_t k, uint32_t p0, bool shared_stash) {
    VisErrs e;
    const int NL = (int) rg_layout_n_layer;
    // lane schedule: PRE(A,0), PRE(B,0), then POST/PRE alternation (sim_layers.schedule)
    struct Step { bool pre; int g; int il; };
    std::vector<Step> sched = { { true, 0, 0 }, { true, 1, 0 } };
    for (int l = 0; l < NL; ++l) {
        sched.push_back({ false, 0, l });
        if (l + 1 < NL) sched.push_back({ true, 0, l + 1 });
        sched.push_back({ false, 1, l });
        if (l + 1 < NL) sched.push_back({ true, 1, l + 1 });
    }

    std::vector<int64_t> pos(R);
    for (uint32_t i = 0; i < R; ++i) pos[i] = (int64_t) p0 + i;
    auto rows_of = [&](int g) {
        std::vector<uint32_t> r;
        for (uint32_t i = 0; i < R; ++i) if ((g == 0) == (i < k)) r.push_back(i);
        return r;
    };

    // (source layer, cache row) written so far; prior ubatches wrote everything < p0/ratio
    std::set<std::pair<int, int64_t>> written;
    std::set<int> lane_stash[2];   // layers whose state this lane has built
    std::set<int> shared;          // the lane-A slot (fixed design)

    for (const Step & s : sched) {
        if (!s.pre) continue;
        const int il = s.il;
        const int64_t ra = rg_layout_compress_ratios[il];
        if (ra == 0) continue;
        const int src = rg_layout_kv_source[il];
        if (is_kv_source(il)) {
            if (s.g == 0) {
                lane_stash[0].insert(il);
                shared.insert(il);
            } else {
                const bool have = shared_stash ? shared.count(il) > 0 : lane_stash[1].count(il) > 0;
                if (!have) {
                    ++e.stash_missing;
                    continue;
                }
            }
            for (uint32_t i : rows_of(s.g)) {
                if ((pos[i] + 1) % ra == 0) {
                    written.insert({ src, pos[i] / ra });
                }
            }
        }
        for (uint32_t i : rows_of(s.g)) {
            const int64_t nvis = (pos[i] + 1) / ra;
            for (int64_t c = 0; c < nvis; ++c) {
                if (c < (int64_t) p0 / ra) continue;
                if (written.count({ src, c }) == 0) {
                    ++e.unwritten;
                    break;
                }
            }
        }
    }
    return e;
}

// ---------------------------------------------------------------------------
// Comparison helpers
// ---------------------------------------------------------------------------
struct Diff {
    double max_abs = 0.0;
    double max_rel = 0.0;   // max |a-b| / max(|a|, 1e-3)
    bool finite = true;
};

Diff diff(const std::vector<float> & a, const std::vector<float> & b) {
    Diff d;
    if (a.size() != b.size() || a.empty()) {
        d.finite = false;
        d.max_abs = INFINITY;
        return d;
    }
    for (size_t i = 0; i < a.size(); ++i) {
        if (!std::isfinite(a[i]) || !std::isfinite(b[i])) {
            d.finite = false;
        }
        const double x = std::fabs((double) a[i] - (double) b[i]);
        d.max_abs = std::max(d.max_abs, x);
        d.max_rel = std::max(d.max_rel, x / std::max(std::fabs((double) a[i]), 1e-3));
    }
    return d;
}

// Structural errors show up as O(1) differences. CPU FP reordering across the two
// batch shapes is far below this.
constexpr double kTolAbs = 1e-3;

} // namespace

int main() {
    ggml_backend_load_all();
    llama_log_set(log_cb, nullptr);

    int failures = 0;

    // ----- 1. host-side visibility (port of sim_layers.py) -----
    {
        const uint32_t cases[][3] = { { 4, 2, 0 }, { 4, 2, 7 }, { 4, 2, 130 }, { 5, 3, 0 }, { 5, 3, 7 }, { 5, 3, 130 },
                                      { 8, 4, 0 }, { 8, 4, 7 }, { 8, 4, 130 }, { 16, 8, 0 }, { 16, 8, 7 }, { 16, 8, 130 } };
        int shared_errs = 0, pre_fix_detected = 0;
        for (const auto & c : cases) {
            const VisErrs sh = visibility(c[0], c[1], c[2], true);
            const VisErrs pl = visibility(c[0], c[1], c[2], false);
            shared_errs += sh.unwritten + sh.stash_missing;
            if (pl.stash_missing > 0) {
                ++pre_fix_detected;
            }
            if (sh.unwritten + sh.stash_missing != 0) {
                fprintf(stderr, "visibility: FAIL R=%u k=%u p0=%u unwritten=%d stash=%d\n",
                        c[0], c[1], c[2], sh.unwritten, sh.stash_missing);
            }
        }
        const bool ok = shared_errs == 0 && pre_fix_detected == (int) (sizeof(cases) / sizeof(cases[0]));
        printf("visibility (real layer table, n_layer=%u): shared-stash errors=%d, per-lane-stash bug detected in %d/%zu cases %s\n",
                rg_layout_n_layer, shared_errs, pre_fix_detected, sizeof(cases) / sizeof(cases[0]), ok ? "PASS" : "FAIL");
        if (!ok) ++failures;
    }

    // ----- 2. end-to-end logits, row groups off vs =2 -----
    llama_model_ptr model = load_model();
    if (!model) {
        fprintf(stderr, "failed to load synthetic DS4.1 model with the real layer table\n");
        return 1;
    }
    printf("model: n_layer=%u kv_sources=[2,8,14,20] index_sources=[2,8,14,20,24,28,32,36] engram=[1,14] ratios=real\n",
            rg_layout_n_layer);

    const uint32_t Rs[] = { 4, 5, 8, 16 };
    const uint32_t p0s[] = { 0, 7, 130 };
    int n_cfg = 0, n_pass = 0;
    double worst_abs = 0.0, worst_rel = 0.0;

    for (uint32_t R : Rs) {
        for (uint32_t p0 : p0s) {
            for (int rb = 0; rb < 2; ++rb) {
                for (int tk = 0; tk < 2; ++tk) {
                    ++n_cfg;
                    const RunResult ref = run_case(model.get(), R, p0, rb, tk, false);
                    const RunResult rg  = run_case(model.get(), R, p0, rb, tk, true);
                    const char * tag = "";
                    bool ok = ref.ok && rg.ok;
                    if (!ok) {
                        tag = "RUN-FAILED";
                    } else if (rg.active == 0 || rg.fallback > 0 || ref.active != 0) {
                        // the row-group run must have really been on the row-group path
                        ok = false;
                        tag = "GATE-NOT-ACTIVE";
                    }
                    Diff dl{}, dt{};
                    if (ok) {
                        dl = diff(ref.logits, rg.logits);
                        double tap_abs = 0.0, tap_rel = 0.0;
                        for (uint32_t lid : tap_layers) {
                            const Diff d = diff(ref.taps.at(lid), rg.taps.at(lid));
                            tap_abs = std::max(tap_abs, d.max_abs);
                            tap_rel = std::max(tap_rel, d.max_rel);
                            if (!d.finite) ok = false;
                            if (d.max_abs > kTolAbs) {
                                fprintf(stderr, "  layer-input tap %u: max_abs=%g\n", lid, d.max_abs);
                            }
                        }
                        dt.max_abs = tap_abs;
                        dt.max_rel = tap_rel;
                        if (!dl.finite) ok = false;
                        if (dl.max_abs > kTolAbs || dt.max_abs > kTolAbs) ok = false;
                        if (!ok && tag[0] == '\0') tag = "DIFF";
                        worst_abs = std::max(worst_abs, std::max(dl.max_abs, dt.max_abs));
                        worst_rel = std::max(worst_rel, std::max(dl.max_rel, dt.max_rel));
                    }
                    printf("R=%-2u p0=%-3u rollback=%d topk_reuse=%d active(rg)=%d fallback(rg)=%d  "
                           "logits max_abs=%.3g max_rel=%.3g  taps max_abs=%.3g  %s%s\n",
                           R, p0, rb, tk, rg.active, rg.fallback, dl.max_abs, dl.max_rel, dt.max_abs,
                           ok ? "PASS" : "FAIL", tag[0] ? (std::string(" [") + tag + "]").c_str() : "");
                    if (rg.fallback > 0) {
                        fprintf(stderr, "  fallback reason: %s", rg.fallback_reason.c_str());
                    }
                    if (ok) ++n_pass; else ++failures;
                }
            }
        }
    }
    printf("row-group end-to-end: %d/%d configs PASS, worst max_abs=%.3g worst max_rel=%.3g (tol abs %.0e)\n",
            n_pass, n_cfg, worst_abs, worst_rel, kTolAbs);
    printf("dsv41 rowgroup e2e: %s\n", failures == 0 ? "PASS" : "FAIL");
    return failures == 0 ? 0 : 1;
}
